package com.pocketmemory.app;

import android.app.*;
import android.content.*;
import android.graphics.*;
import android.graphics.drawable.*;
import android.net.Uri;
import android.os.*;
import android.text.*;
import android.view.*;
import android.widget.*;
import org.json.*;
import java.io.*;
import java.nio.charset.StandardCharsets;
import java.time.LocalDate;
import java.util.*;

/** Pocket Memory Llama hackathon planning workflow. */
public final class MainActivity extends Activity {
    static final int INK=Color.rgb(32,30,37),PAPER=Color.rgb(245,241,249),PINK=Color.rgb(255,139,210),AQUA=Color.rgb(173,242,235),YELLOW=Color.rgb(246,236,107),LILAC=Color.rgb(205,184,255),MUTED=Color.rgb(94,86,103);
    PlanApp app;LinearLayout root,body;ScrollView scroll;String screen="Sources";EditText goalInput;Button applyButton;String showingPlan="";boolean editGoal=false;
    @Override public void onCreate(Bundle saved){super.onCreate(saved);app=(PlanApp)getApplication();if(saved!=null)screen=saved.getString("screen","Sources");else if(app.store.latest()!=null)screen="Plan";getWindow().setSoftInputMode(WindowManager.LayoutParams.SOFT_INPUT_ADJUST_RESIZE);getWindow().setDecorFitsSystemWindows(false);render();}
    @Override protected void onResume(){super.onResume();app.listener=this::render;render();}
    @Override protected void onPause(){app.listener=null;super.onPause();}
    @Override protected void onSaveInstanceState(Bundle b){b.putString("screen",screen);super.onSaveInstanceState(b);}
    int dp(float x){return Math.round(getResources().getDisplayMetrics().density*x);}
    LinearLayout column(){LinearLayout v=new LinearLayout(this);v.setOrientation(LinearLayout.VERTICAL);return v;}
    TextView text(String value,int size,int color,boolean bold){TextView v=new TextView(this);v.setText(value);v.setTextSize(size);v.setTextColor(color);v.setLineSpacing(dp(2),1);if(bold)v.setTypeface(Typeface.DEFAULT,Typeface.BOLD);return v;}
    GradientDrawable shape(int fill,int radius){GradientDrawable d=new GradientDrawable();d.setColor(fill);d.setCornerRadius(dp(radius));d.setStroke(dp(2),INK);return d;}
    android.graphics.drawable.Drawable sticker(int fill,int radius){LayerDrawable layer=new LayerDrawable(new android.graphics.drawable.Drawable[]{shape(INK,radius),shape(fill,radius)});layer.setLayerInset(0,dp(4),dp(5),0,0);layer.setLayerInset(1,0,0,dp(4),dp(5));return layer;}
    void add(LinearLayout parent,View child){parent.addView(child,new LinearLayout.LayoutParams(-1,-2));}
    void gap(LinearLayout parent,int height){View v=new View(this);parent.addView(v,new LinearLayout.LayoutParams(1,dp(height)));}
    LinearLayout card(int color){LinearLayout v=column();v.setPadding(dp(16),dp(16),dp(20),dp(21));v.setBackground(sticker(color,18));return v;}
    interface Action{void run()throws Exception;}
    Button button(String label,int color,Action action){Button b=new Button(this);b.setText(label);b.setAllCaps(false);b.setTextSize(14);b.setTypeface(Typeface.DEFAULT,Typeface.BOLD);b.setTextColor(INK);b.setMinHeight(dp(52));b.setPadding(dp(12),dp(10),dp(16),dp(15));b.setBackground(sticker(color,15));b.setOnClickListener(v->{try{action.run();}catch(Exception e){app.message=e.getMessage();Toast.makeText(this,app.message,Toast.LENGTH_LONG).show();render();}});return b;}
    EditText input(String hint,String value,boolean multiline){EditText e=new EditText(this);e.setText(value);e.setHint(hint);e.setTextSize(15);e.setTextColor(INK);e.setHintTextColor(MUTED);e.setPadding(dp(13),dp(12),dp(13),dp(12));e.setBackground(shape(Color.WHITE,12));e.setSingleLine(!multiline);if(multiline){e.setMinLines(2);e.setMaxLines(6);e.setGravity(Gravity.TOP);}return e;}
    void go(String next){if(!screen.equals(next))scroll=null;screen=next;render();}
    void render(){
        int oldScroll=scroll==null?0:scroll.getScrollY();root=column();root.setBackground(new Grid());root.setPadding(dp(17),dp(20),dp(17),dp(16));
        root.setOnApplyWindowInsetsListener((view,insets)->{android.graphics.Insets bars=insets.getInsets(WindowInsets.Type.systemBars());view.setPadding(dp(17),bars.top+dp(12),dp(17),bars.bottom+dp(12));return insets;});setContentView(root);root.requestApplyInsets();
        LinearLayout heading=new LinearLayout(this);heading.setGravity(Gravity.CENTER_VERTICAL);TextView logo=text("POCKET MEMORY",25,INK,true);heading.addView(logo,new LinearLayout.LayoutParams(0,-2,1));TextView mark=text("✦",30,INK,true);mark.setPadding(dp(13),dp(3),dp(13),dp(3));mark.setBackground(shape(YELLOW,18));heading.addView(mark);add(root,heading);gap(root,5);add(root,text("Llama edition · Hackathon planning workflow",11,MUTED,false));gap(root,9);
        TextView badge=text("BUILT WITH LLAMA · 3.2 3B · ON DEVICE",11,INK,true);badge.setPadding(dp(10),dp(6),dp(10),dp(6));badge.setBackground(shape(AQUA,11));add(root,badge);gap(root,13);
        scroll=new ScrollView(this);scroll.setFillViewport(false);body=column();scroll.addView(body);root.addView(scroll,new LinearLayout.LayoutParams(-1,0,1));
        if(screen.equals("Sources"))sources();else if(screen.equals("Plan"))plan();else if(screen.equals("Tasks"))tasks();else model();
        gap(root,12);LinearLayout nav=new LinearLayout(this);for(String name:new String[]{"Sources","Plan","Tasks","Model"}){Button b=button(name,screen.equals(name)?YELLOW:Color.WHITE,()->go(name));b.setTextSize(12);b.setPadding(dp(3),dp(8),dp(6),dp(12));LinearLayout.LayoutParams params=new LinearLayout.LayoutParams(0,-2,1);params.setMargins(0,0,dp(5),0);nav.addView(b,params);}add(root,nav);
        root.post(()->{WindowInsetsController control=root.getWindowInsetsController();if(control!=null)control.setSystemBarsAppearance(WindowInsetsController.APPEARANCE_LIGHT_STATUS_BARS|WindowInsetsController.APPEARANCE_LIGHT_NAVIGATION_BARS,WindowInsetsController.APPEARANCE_LIGHT_STATUS_BARS|WindowInsetsController.APPEARANCE_LIGHT_NAVIGATION_BARS);scroll.scrollTo(0,oldScroll);});
    }
    void title(String title,String detail){add(body,text(title,27,INK,true));gap(body,5);add(body,text(detail,14,MUTED,false));gap(body,16);}
    void sources(){
        title("Small notes.\nUseful next steps.","Llama selects actions from your notes. You review the plan before it creates local tasks.");
        add(body,button("+ Add a source note",PINK,()->edit(null)));gap(body,12);
        List<PlanStore.Note> notes=app.store.notes();if(notes.isEmpty()){LinearLayout c=card(YELLOW);add(c,text("Try the Lakeview case",20,INK,true));gap(c,8);add(c,text("A fictional client demo, a packing list, a changed room and a separate party to ignore.",14,INK,false));gap(c,12);add(c,button("Load fictional example",Color.WHITE,()->{ExampleData.add(app.store);app.goal=ExampleData.GOAL;app.day="2026-11-02";render();}));add(body,c);return;}
        add(body,text(notes.size()+" source notes · stored in this app",12,MUTED,false));gap(body,10);
        for(PlanStore.Note n:notes){LinearLayout c=card(Color.WHITE);add(c,text(n.title,18,INK,true));gap(c,6);TextView preview=text(n.body,14,INK,false);preview.setMaxLines(5);preview.setEllipsize(android.text.TextUtils.TruncateAt.END);add(c,preview);gap(c,8);add(c,text("Source "+n.id+" · revision "+n.version,11,MUTED,false));gap(c,9);add(c,button("Review / edit source",AQUA,()->edit(n)));add(body,c);gap(body,14);}
    }
    void edit(PlanStore.Note note){LinearLayout form=column();form.setPadding(dp(20),dp(10),dp(20),dp(10));EditText name=input("Source title",note==null?"":note.title,false),content=input("Write the instruction and its context",note==null?"":note.body,true);add(form,name);gap(form,10);add(form,content);AlertDialog dialog=new AlertDialog.Builder(this).setTitle(note==null?"New source":"Edit source · revision "+note.version).setView(form).setPositiveButton("Save",null).setNegativeButton("Cancel",null).create();dialog.setOnShowListener(x->dialog.getButton(AlertDialog.BUTTON_POSITIVE).setOnClickListener(v->{try{app.store.saveNote(note==null?0:note.id,name.getText().toString(),content.getText().toString());dialog.dismiss();app.message="Source saved. Earlier plans keep their original evidence.";render();}catch(Exception e){content.setError(e.getMessage());}}));dialog.show();}
    void progress(){LinearLayout row=new LinearLayout(this);for(String name:new String[]{"Read","Llama","Check","Review"}){TextView v=text(name,11,INK,true);v.setGravity(Gravity.CENTER);v.setPadding(dp(3),dp(7),dp(3),dp(7));v.setBackground(shape(app.stage.equals(name)?PINK:Color.WHITE,10));LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(0,-2,1);p.setMargins(0,0,dp(5),0);row.addView(v,p);if(app.stage.equals(name)&&android.animation.ValueAnimator.areAnimatorsEnabled()){v.setAlpha(.55f);v.animate().alpha(1).setDuration(220).start();}}add(body,row);gap(body,12);}
    void plan(){
        title("A plan you can approve.","Llama selects source actions. The app orders workflow phases. You review before tasks are created.");progress();
        PlanStore.Plan p=app.store.latest();
        if(p==null||editGoal){
        goalInput=input("What do you want to get done?",app.goal,true);add(body,goalInput);goalInput.addTextChangedListener(new TextWatcher(){public void beforeTextChanged(CharSequence s,int a,int c,int f){}public void onTextChanged(CharSequence s,int a,int before,int count){app.goal=s.toString();updateApply();}public void afterTextChanged(Editable e){}});gap(body,9);
        add(body,button("Task date · "+app.day,Color.WHITE,()->{LocalDate d=LocalDate.parse(app.day);new DatePickerDialog(this,(picker,y,m,day)->{app.day=LocalDate.of(y,m+1,day).toString();app.message="Date changed. Build a plan for the selected date.";render();},d.getYear(),d.getMonthValue()-1,d.getDayOfMonth()).show();}));gap(body,10);
        }else{add(body,button("Change goal or task date",Color.WHITE,()->{editGoal=true;render();}));gap(body,10);}
        Button build=button(app.busy?"Stop planning":"Build with Llama",PINK,()->{if(app.busy)app.stop();else if(!app.model.installed()||!app.model.accepted())go("Model");else{editGoal=false;app.build();}});add(body,build);gap(body,12);
        if(!app.message.isBlank()){LinearLayout status=card(app.message.contains("changed")?YELLOW:AQUA);add(status,text(app.message,13,INK,false));add(body,status);gap(body,14);}
        showingPlan=p==null?"":p.id;applyButton=null;
        if(p==null){add(body,text("Your reviewed action plan will appear here. A plan is a proposal, not an automatic task batch.",14,MUTED,false));return;}
        LinearLayout summary=card(LILAC);add(summary,text(p.status.equals("applied")?"✓ Tasks added":p.status.equals("undone")?"Batch undone · review again":"Review this plan",20,INK,true));gap(summary,7);add(summary,text(p.goal,14,INK,true));add(summary,text("Task date: "+p.day,12,INK,false));gap(summary,5);add(summary,text(app.store.fresh(p)?"Sources match this plan.":"NOTES CHANGED · Build a fresh plan.",12,INK,true));add(body,summary);gap(body,14);
        for(int i=0;i<p.actions.length();i++){final int index=i;JSONObject action=p.actions.optJSONObject(i);LinearLayout c=card(Color.WHITE);add(c,text(action.optString("phase"),11,MUTED,true));gap(c,5);CheckBox chosen=new CheckBox(this);chosen.setText((i+1)+". "+action.optString("text"));chosen.setTextSize(16);chosen.setTextColor(INK);chosen.setMinHeight(dp(48));chosen.setButtonTintList(android.content.res.ColorStateList.valueOf(INK));chosen.setChecked(action.optBoolean("selected",true));chosen.setEnabled(!p.status.equals("applied")&&!app.busy);add(c,chosen);gap(c,7);add(c,text("Source: "+action.optString("source_title")+" · revision "+action.optInt("source_version"),11,MUTED,true));gap(c,8);add(c,button("Inspect evidence",AQUA,()->evidence(action)));chosen.setOnCheckedChangeListener((v,checked)->{try{app.store.select(p.id,index,checked);updateApply();}catch(Exception e){Toast.makeText(this,e.getMessage(),Toast.LENGTH_LONG).show();}});add(body,c);gap(body,13);}
        if(p.status.equals("applied")){add(body,button("View created tasks",PINK,()->go("Tasks")));gap(body,10);add(body,button("Undo this task batch",Color.WHITE,()->{app.store.undo(p.id);app.message="This batch was undone. Other tasks were preserved.";render();}));}
        else{applyButton=button("Add reviewed tasks",PINK,()->{app.store.apply(p.id);app.message="Reviewed tasks added. Repeating this action cannot duplicate the batch.";render();});add(body,applyButton);updateApply();}
    }
    void updateApply(){if(applyButton==null||showingPlan.isEmpty())return;PlanStore.Plan p=app.store.plan(showingPlan);int count=0;for(int i=0;i<p.actions.length();i++)if(p.actions.optJSONObject(i).optBoolean("selected",true))count++;boolean fresh=app.store.fresh(p)&&p.goal.equals(app.goal)&&p.day.equals(app.day);applyButton.setText(fresh?"Add "+count+" reviewed tasks":"Notes or goal changed · Build again");applyButton.setEnabled(fresh&&count>0&&!app.busy);applyButton.setAlpha(applyButton.isEnabled()?1f:.55f);}
    void evidence(JSONObject a){LinearLayout content=column();content.setPadding(dp(20),dp(10),dp(20),dp(15));add(content,text("Used for this plan",16,INK,true));add(content,text(a.optString("source_quote"),15,INK,false));PlanStore.Note now=app.store.note(a.optLong("source_id"));if(now==null||now.version!=a.optInt("source_version")){gap(content,15);add(content,text("Current source",16,INK,true));add(content,text(now==null?"Source removed.":now.body,15,INK,false));}ScrollView s=new ScrollView(this);s.addView(content);new AlertDialog.Builder(this).setTitle(a.optString("source_title")).setView(s).setPositiveButton("Close",null).show();}
    void tasks(){title("Reviewed. Added.\nStill in your control.","These are local to-do tasks created from approved plans.");List<JSONObject> tasks=app.store.tasks();if(tasks.isEmpty()){add(body,text("No tasks yet. Build and review a plan first.",15,MUTED,false));add(body,button("Open Plan",PINK,()->go("Plan")));return;}for(JSONObject task:tasks){LinearLayout c=card(Color.WHITE);CheckBox done=new CheckBox(this);done.setText(task.optString("title"));done.setTextSize(16);done.setTextColor(INK);done.setMinHeight(dp(48));done.setChecked(task.optInt("done")==1);done.setOnCheckedChangeListener((v,checked)->app.store.complete(task.optLong("id"),checked));add(c,done);gap(c,7);add(c,text("Due "+task.optString("day")+" · "+task.optString("source_title"),12,MUTED,false));gap(c,9);add(c,button("Source context",AQUA,()->document(task.optString("source_title"),task.optString("source_quote"))));add(body,c);gap(body,14);}}
    void model(){
        title("One Meta model.\nOn your phone.","No inference API account. Model downloads happen in your browser; this app has no internet permission.");LinearLayout c=card(AQUA);add(c,text("Llama 3.2 · 3B Instruct",22,INK,true));gap(c,7);add(c,text("Built with Llama · Q4_K_M\n2.02 GB model download\n8 GB phone RAM minimum; 12 GB recommended\nRAM guidance is an estimate, not a performance guarantee.",14,INK,false));gap(c,12);add(c,text(app.model.installed()?"✓ Installed and checksum verified":"Import the pinned model to start planning.",14,INK,true));gap(c,12);
        Button download=button("Download pinned Llama file",Color.WHITE,()->terms(()->startActivity(new Intent(Intent.ACTION_VIEW,Uri.parse(app.model.url())))));download.setEnabled(!app.busy);add(c,download);gap(c,10);Button importModel=button(app.busy?"Working…":"Import downloaded GGUF",PINK,()->terms(()->{Intent i=new Intent(Intent.ACTION_OPEN_DOCUMENT);i.setType("*/*");i.addCategory(Intent.CATEGORY_OPENABLE);startActivityForResult(i,71);}));importModel.setEnabled(!app.busy);add(c,importModel);gap(c,10);add(c,button("Read Llama licence",Color.WHITE,()->document("Llama 3.2 licence",asset("licenses/llama-3.2.txt"))));gap(c,8);add(c,button("Llama acceptable use",Color.WHITE,()->document("Llama acceptable use",asset("licenses/llama-3.2-use-policy.txt"))));add(body,c);gap(body,14);if(!app.message.isBlank())add(body,text(app.message,14,INK,true));gap(body,13);add(body,text("Sources, plans, tasks and model files stay in this app's Android storage. Review every proposed task before applying it.",12,MUTED,false));
    }
    String asset(String name)throws IOException{try(InputStream in=getAssets().open(name)){return new String(in.readAllBytes(),StandardCharsets.UTF_8);}}
    void document(String title,String value){TextView text=text(value,14,INK,false);text.setPadding(dp(20),dp(12),dp(20),dp(16));text.setTextIsSelectable(true);ScrollView s=new ScrollView(this);s.addView(text);new AlertDialog.Builder(this).setTitle(title).setView(s).setPositiveButton("Close",null).show();}
    void terms(Runnable next){if(app.model.accepted()){next.run();return;}LinearLayout form=column();form.setPadding(dp(20),dp(10),dp(20),dp(15));add(form,text("Built with Llama. Review the Llama 3.2 Community License and Acceptable Use Policy before downloading or using this model.",14,INK,false));gap(form,9);add(form,button("Complete licence",Color.WHITE,()->document("Llama licence",asset("licenses/llama-3.2.txt"))));gap(form,8);add(form,button("Acceptable Use Policy",Color.WHITE,()->document("Llama acceptable use",asset("licenses/llama-3.2-use-policy.txt"))));CheckBox check=new CheckBox(this);check.setText("I accept the model's licence and use restrictions.");check.setMinHeight(dp(48));add(form,check);AlertDialog d=new AlertDialog.Builder(this).setTitle("Llama model terms").setView(form).setPositiveButton("Accept & continue",null).setNegativeButton("Cancel",null).create();d.setOnShowListener(v->d.getButton(AlertDialog.BUTTON_POSITIVE).setOnClickListener(x->{if(!check.isChecked()){check.setError("Review and accept the terms first.");return;}app.model.accept();d.dismiss();next.run();}));d.show();}
    @Override protected void onActivityResult(int request,int result,Intent data){super.onActivityResult(request,result,data);if(request!=71||result!=RESULT_OK||data==null||data.getData()==null)return;Uri uri=data.getData();if(app.busy)return;app.busy=true;app.cancelled.set(false);app.message="Importing and verifying Llama…";render();app.worker.execute(()->{try{app.model.importFile(uri,app.cancelled,(done,total)->{app.message="Importing Llama · "+(done*100/total)+"%";app.changed();});app.message="Llama is installed and verified. Open Plan to get started.";}catch(Exception e){app.message=e.getMessage();}finally{app.busy=false;app.changed();}});}
    final class Grid extends android.graphics.drawable.Drawable {final Paint paint=new Paint();@Override public void draw(Canvas canvas){canvas.drawColor(PAPER);paint.setColor(Color.rgb(228,222,234));paint.setStrokeWidth(dp(.7f));int step=dp(28);for(int x=0;x<getBounds().right;x+=step)canvas.drawLine(x,0,x,getBounds().bottom,paint);for(int y=0;y<getBounds().bottom;y+=step)canvas.drawLine(0,y,getBounds().right,y,paint);}@Override public void setAlpha(int a){}@Override public void setColorFilter(ColorFilter f){}@Override public int getOpacity(){return PixelFormat.OPAQUE;}}
}
